    [Fact]
    public async Task BhvAuth051PasswordWrapperUsesItsTokenUrlThenItsRefreshUrlAndScopes()
    {
        var transport = new ScriptedApiClient();
        transport.Enqueue(
            "{\"access_token\":\"tok1\",\"refresh_token\":\"ref1\",\"expires_in\":0}"
        );
        transport.Enqueue("{\"access_token\":\"tok2\",\"expires_in\":3600}");
        var auth = new LegacyAuthPasswordAuthenticator(Host, "cid", "csecret", "alice", "s3cret");
        auth.SetApiClient(transport);

        await auth.GetAuthHeadersAsync(TestContext.Current.CancellationToken);
        await auth.GetAuthHeadersAsync(TestContext.Current.CancellationToken);

        Assert.Equal(2, transport.Requests.Count);
        Assert.Equal("https://auth.example.com/oauth/token", transport.Requests[0].Url.AbsoluteUri);
        Assert.Contains(
            "grant_type=password",
            transport.Requests[0].Body,
            StringComparison.Ordinal
        );
        Assert.Contains("scope=read", transport.Requests[0].Body, StringComparison.Ordinal);
        Assert.Equal(
            "https://auth.example.com/oauth/refresh",
            transport.Requests[1].Url.AbsoluteUri
        );
        Assert.Contains(
            "grant_type=refresh_token",
            transport.Requests[1].Body,
            StringComparison.Ordinal
        );
    }

